"""Few-shot prompt examples used by the math and AQuA tasks.

Each constant is a plain list of dictionaries with ``question`` and ``answer``
keys. Answers always end with "The answer is ..." so that the parser can
extract the final prediction from model completions that follow the same
format.
"""

MATH_FEW_SHOT: list[dict] = [
    {
        "question": "What is the remainder when $3^{2023}$ is divided by 4?",
        "answer": (
            "Since $3 \\equiv -1 \\pmod{4}$, we have "
            "$3^{2023} \\equiv (-1)^{2023} \\equiv -1 \\equiv 3 \\pmod{4}$.\n"
            "The answer is 3"
        ),
    },
    {
        "question": (
            "If $f(x) = 5x - 4$, what is $f(f(f(2)))$?"
        ),
        "answer": (
            "$f(2) = 5(2) - 4 = 6$, so $f(f(2)) = f(6) = 5(6) - 4 = 26$, "
            "and $f(f(f(2))) = f(26) = 5(26) - 4 = 126$.\n"
            "The answer is 126"
        ),
    },
    {
        "question": "What is the greatest common divisor of 272 and 1479?",
        "answer": (
            "Using the Euclidean algorithm: $1479 = 5 \\cdot 272 + 119$, "
            "$272 = 2 \\cdot 119 + 34$, and $119 = 3 \\cdot 34 + 17$, "
            "and $34 = 2 \\cdot 17$. The last nonzero remainder is 17.\n"
            "The answer is 17"
        ),
    },
]

AQUA_FEW_SHOT: list[dict] = [
    {
        "question": (
            "A train running at the speed of 60 km/hr crosses a pole in 9 "
            "seconds. What is the length of the train?\n"
            "A) 120 metres\nB) 180 metres\nC) 324 metres\n"
            "D) 150 metres\nE) None of these"
        ),
        "answer": (
            "Speed = $60 \\times \\frac{5}{18}$ m/sec $= \\frac{50}{3}$ m/sec. "
            "Length of the train = speed $\\times$ time $= \\frac{50}{3} "
            "\\times 9 = 150$ metres.\n"
            "The answer is D"
        ),
    },
    {
        "question": (
            "What is the sum of the first 10 positive integers?\n"
            "A) 45\nB) 50\nC) 55\nD) 60\nE) 65"
        ),
        "answer": (
            "The sum of the first $n$ positive integers is "
            "$\\frac{n(n+1)}{2} = \\frac{10 \\cdot 11}{2} = 55$.\n"
            "The answer is C"
        ),
    },
]

