import time
from unittest.mock import patch

import pytest
import sympy

from math_verify import (
    ExprExtractionConfig, LatexExtractionConfig, parse, verify,
)
from math_verify import StringExtractionConfig


def compare_strings(
    gold: str,
    pred: str,
    match_types: list = ["latex", "expr"],
    precision: int = 6,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
):
    extraction_targets = []
    for match_type in match_types:
        if match_type == "latex":
            extraction_targets.append(LatexExtractionConfig(boxed_match_priority=0))
        elif match_type == "expr":
            extraction_targets.append(ExprExtractionConfig())
    gold_parsed = parse(gold, extraction_targets)
    pred_parsed = parse(pred, extraction_targets)
    return verify(gold_parsed, pred_parsed, float_rounding=precision, strict=strict, allow_set_relation_comp=allow_set_relation_comp)


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param("7425000", "7,425,000", {"match_types": ["expr"]}, 1, id="thousands-separator"),
        pytest.param("1000.99", "1000,99", {"match_types": ["expr"]}, 1, id="comma-decimal"),
        pytest.param("1000.99", "$1,000.99", {"match_types": ["expr"]}, 1, id="currency-thousands"),
    ],
)
def test_numbers(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param("$9$", "Answer $ 9 $", {"match_types": ["latex"]}, 1, id="inline-math"),
        pytest.param("$9$", r"Answer \[ 9 \]", {"match_types": ["latex"]}, 1, id="display-math-brackets"),
        pytest.param("$1/3$", r"$\boxed{\frac{1}{3}}$", {"match_types": ["latex"]}, 1, id="boxed-fraction"),
        pytest.param(
            r"$1 \pm \sqrt{19}$",
            r"By the quadratic formula, $x = \boxed{1 \pm \sqrt{19}}.$",
            {},
            1,
            id="boxed-in-sentence",
        ),
    ],
)
def test_latex_extraction(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param("$1/3$", r"$\frac13 $", {"match_types": ["latex"]}, 1, id="frac-no-braces"),
        pytest.param(r"$\sqrt{3}$", r"$\sqrt3 $", {"match_types": ["latex"]}, 1, id="sqrt-no-braces"),
        pytest.param("$1/3$", r"$\cfrac{1}{3} $", {"match_types": ["latex"]}, 1, id="cfrac"),
        pytest.param("$1/3$", r"$k = \frac{1}{3}$", {"match_types": ["latex"]}, 1, id="simple-assignment"),
    ],
)
def test_latex_normalization(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param(r"$28\%$", "28 percent", {}, 1, id="percent-word"),
        pytest.param(r"$28\%$", "28 pct", {}, 1, id="pct-abbreviation"),
        pytest.param(r"$28\%$", r"$\boxed{28}$ pct", {}, 1, id="boxed-pct"),
    ],
)
def test_percentages(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param("$[0,1)$", "$[0,1)$", {}, 1, id="same-interval"),
        pytest.param("$[0,9)$", "$[0,1)$", {}, 0, id="different-intervals"),
        pytest.param("$(0,9)$", "$[0,9)$", {}, 0, id="open-vs-closed"),
        pytest.param(r"$(\frac{3}{5},\frac{8}{3}]$", "$(0.6,2.6667]$", {}, 1, id="interval-decimal-bounds"),
        pytest.param("$$-793 < a < 10$$", "$$(-793, 10)$$", {}, 1, id="relation-vs-interval"),
    ],
)
def test_sets_intervals(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param(
            "$34x+45y-20z+100=0$",
            "$-34x-45y+20z-100=0$",
            {},
            1,
            id="negated-equation",
        ),
    ],
)
def test_relations(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param(
            r"$\boxed{\begin{pmatrix}1 & 2 \\ 3 & 4\end{pmatrix}}$",
            r"$\boxed{\begin{pmatrix}1 & 2 \\ 3 & 4\end{pmatrix}}$",
            {},
            1,
            id="boxed-identical-pmatrix",
        ),
        pytest.param(
            r"$\begin{pmatrix}x & y \\ z & w\end{pmatrix}$",
            r"$\begin{pmatrix}a & b \\ c & d\end{pmatrix}$",
            {"strict": True},
            0,
            id="matrix-different-symbols-strict",
        ),
        pytest.param(
            r"$\begin{pmatrix}x & y \\ z & w\end{pmatrix}$",
            r"$\begin{pmatrix}a & b \\ c & d\end{pmatrix}$",
            {"strict": False},
            1,
            id="matrix-different-symbols-non-strict",
        ),
    ],
)
def test_matrices(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param(
            r"$\frac{x+2}{7}$",
            r"$\frac{x}{7}+\frac{2}{7}$",
            {},
            1,
            id="split-fraction",
        ),
        pytest.param(
            r"$\tan^2(y)+1$",
            r"$\sec^2(y)$",
            {},
            1,
            id="trig-identity",
        ),
        pytest.param(
            r"$\frac{\sqrt{\sqrt{11}+\sqrt{194}}}{15+2\sqrt{33}}$",
            r"$\frac{\sqrt{\sqrt{11}+\sqrt{194}}}{2\sqrt{33}+15}$",
            {},
            1,
            id="nested-sqrt-commuted-denominator",
        ),
        pytest.param(
            r"$\frac{34}{16}+\frac{\sqrt{1358}}{16}$",
            "$4$",
            {"precision": 6},
            0,
            id="sqrt-expression-not-four",
        ),
    ],
)
def test_complex_expressions(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param("$f(x)$", "$f(y)$", {"strict": True}, 0, id="function-different-vars-strict"),
        pytest.param("$f(x)$", "$f(y)$", {"strict": False}, 1, id="function-different-vars-non-strict"),
        pytest.param(r"$\sin(x)+\cos(x)$", r"$\sin(t)+\cos(t)$", {"strict": True}, 0, id="trig-different-vars-strict"),
        pytest.param(r"$\sin(x)+\cos(x)$", r"$\sin(t)+\cos(t)$", {"strict": False}, 1, id="trig-different-vars-non-strict"),
        pytest.param(r"$\frac{1}{3}$", "$0.333333$", {"strict": True}, 1, id="fraction-vs-decimal-strict"),
    ],
)
def test_strict_mode(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param(r"$(1,\frac{9}{2})$", "$(1,4.5)$", {"precision": 6}, 1, id="tuple-decimal"),
        pytest.param(
            r"$(\begin{pmatrix}\frac{1}{3}\\ \frac{1}{5} \end{pmatrix})$",
            r"$\begin{pmatrix}0.33\\0.2 \end{pmatrix}$",
            {"precision": 2},
            1,
            id="matrix-low-precision",
        ),
        pytest.param(r"$(\frac{3}{5},\frac{8}{3}]$", "$(0.6,2.6667]$", {"precision": 2}, 1, id="interval-low-precision"),
        pytest.param(r"$\frac{1}{3}$", "$0.33$", {"precision": 2}, 1, id="third-precision-2"),
        pytest.param(r"$\frac{1}{3}$", "$0.33$", {"precision": 6}, 0, id="third-precision-6"),
        pytest.param(r"$\frac{1}{12}$", "$0.0833333333333333$", {}, 1, id="twelfth-long-decimal"),
    ],
)
def test_precision(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


@pytest.mark.parametrize(
    "gold,pred,kwargs,expected",
    [
        pytest.param("2", "AZYUK2A", {"match_types": ["expr"]}, 0, id="garbage-pred-no-parse"),
    ],
)
def test_edge_cases(gold, pred, kwargs, expected):
    assert compare_strings(gold, pred, **kwargs) == expected


def test_parse_outputs():
    assert parse("") == []
    assert parse("AZYUK2A") == []
    assert parse("Answer: €$%^&*()123.45") == [123.45]
    assert parse(r"$\frac{1}{2}$") == [sympy.Rational(1, 2)]
    assert float(parse("$0.5$")[0]) == pytest.approx(0.5)


def test_verify_parse_basic():
    gold = parse(r"$\frac{1}{2}$")
    answer = parse("$0.5$")
    assert verify(gold, answer)


@pytest.mark.timeout
def test_parse_expr_timeout():
    with patch("math_verify.parser.parse_expr", lambda *args, **kwargs: time.sleep(5)):
        assert parse("1+1", parsing_timeout=1, extraction_mode="first_match", fallback_mode="no_fallback") == []


@pytest.mark.timeout
def test_latex2sympy_timeout():
    with patch("math_verify.parser.latex2sympy", lambda *args, **kwargs: time.sleep(5)):
        assert parse("$1+1$", parsing_timeout=1, extraction_mode="first_match", fallback_mode="no_fallback") == []


@pytest.mark.timeout
def test_verify_timeout():
    gold = parse("1+1")
    answer = parse("1+1")
    with patch("math_verify.grader.sympy_expr_eq", lambda *args, **kwargs: time.sleep(5)):
        assert verify(gold, answer, timeout_seconds=1) is False


def test_string_extraction():
    assert parse("The answer is A.", [StringExtractionConfig(lowercase=False)]) == ["A", "A"]
    assert parse("The answer is A.", [StringExtractionConfig(lowercase=True)]) == ["a", "A"]
    assert parse("The answer is U.", [StringExtractionConfig(strings=("U",))]) == ["u", "U"]
    assert parse("No valid answer here", [StringExtractionConfig()]) == []


def test_boxed_priority():
    assert parse(
        "final answer is $9999$, \\boxed{1}",
        [LatexExtractionConfig(boxed_match_priority=0)],
    ) == [1]
    assert parse(
        "final answer is $9999$, \\boxed{1}",
        [LatexExtractionConfig(boxed_match_priority=100)],
    ) == [9999]
    assert parse(
        "\\boxed{1}",
        [LatexExtractionConfig(boxed_match_priority=-1)],
        fallback_mode="no_fallback",
    ) == []

