"""Grader for math-verify: compares parsed sympy expressions with a gold answer.

The main entry point is :func:`verify`, which takes (lists of) parsed sympy
objects or strings and returns whether any (gold, target) pair matches.
The heavy lifting is done by :func:`sympy_expr_eq`, which applies a cascade
of comparison strategies (structural, numeric, relational, set, matrix,
symbolic) with configurable float rounding and symbol-name strictness.
"""

import signal
from itertools import permutations
from typing import List, Optional, Union

from sympy import (
    And,
    Basic,
    Eq,
    FiniteSet,
    Ge,
    Gt,
    Intersection,
    Interval,
    Le,
    Lt,
    N,
    Ne,
    Or,
    Set,
    Symbol,
    Tuple,
    Union as SympyUnion,
    simplify,
    solve_univariate_inequality,
    sympify,
    trigsimp,
)
from sympy.core.relational import (
    Equality,
    GreaterThan,
    LessThan,
    Relational,
    StrictGreaterThan,
    StrictLessThan,
    Unequality,
)
from sympy.matrices.matrixbase import MatrixBase

try:
    from math_verify.errors import TimeoutException
except ImportError:  # pragma: no cover - fallback for direct module use
    from .errors import TimeoutException


# Reverse-direction map for relationals: e1 == -e2 is only equivalent when the
# relation direction is exactly flipped (Eq and Ne are their own reverses).
_REVERSE_RELATIONAL = {
    GreaterThan: LessThan,
    LessThan: GreaterThan,
    StrictGreaterThan: StrictLessThan,
    StrictLessThan: StrictGreaterThan,
    Equality: Equality,
    Unequality: Unequality,
}


def _free_symbols(expr) -> set:
    """Union of free symbols of an expression (elements for containers)."""
    try:
        return set(expr.free_symbols)
    except Exception:
        pass
    symbols = set()
    elements = ()
    if isinstance(expr, MatrixBase):
        elements = list(expr)
    elif isinstance(expr, (Tuple, FiniteSet, SympyUnion, And, Or)):
        elements = expr.args
    for element in elements:
        try:
            symbols |= set(element.free_symbols)
        except Exception:
            continue
    return symbols


def _symbol_names(expr) -> set:
    """Set of free-symbol names of an expression."""
    return {str(symbol) for symbol in _free_symbols(expr)}


def _numeric_close(a, b, float_rounding: int, numeric_precision: int) -> bool:
    """True iff |a - b| rounds to 0 at ``float_rounding`` decimal places."""
    try:
        if a == b:
            return True
        diff = abs(N(a - b, numeric_precision))
        return round(diff, float_rounding) == 0
    except Exception:
        return False


def _is_zero(expr, float_rounding: int, numeric_precision: int) -> bool:
    """True iff expr is symbolically zero (or numerically zero when constant)."""
    try:
        if expr == 0:
            return True
    except Exception:
        pass
    try:
        if not _free_symbols(expr):
            # Symbol-free: fall back to an evalf-based numeric comparison.
            return _numeric_close(expr, 0, float_rounding, numeric_precision)
        if simplify(expr) == 0:
            return True
        if trigsimp(expr) == 0:
            return True
    except Exception:
        pass
    return False


def _interval_eq(gold: Interval, target: Interval, float_rounding: int, numeric_precision: int) -> bool:
    """True iff two intervals have matching openness and close endpoints.

    Also accepts swapped endpoints so that e.g. [0, 1] ~ [1, 0].
    """
    direct = (
        gold.left_open == target.left_open
        and gold.right_open == target.right_open
        and _numeric_close(gold.inf, target.inf, float_rounding, numeric_precision)
        and _numeric_close(gold.sup, target.sup, float_rounding, numeric_precision)
    )
    swapped = (
        gold.left_open == target.right_open
        and gold.right_open == target.left_open
        and _numeric_close(gold.inf, target.sup, float_rounding, numeric_precision)
        and _numeric_close(gold.sup, target.inf, float_rounding, numeric_precision)
    )
    return direct or swapped


def _union_eq(gold: SympyUnion, target: SympyUnion, float_rounding: int, numeric_precision: int) -> bool:
    """True iff two unions have the same number of pairwise-matching intervals."""
    gold_args, target_args = list(gold.args), list(target.args)
    if len(gold_args) != len(target_args):
        return False
    if not all(isinstance(arg, Interval) for arg in gold_args + target_args):
        return False

    def sort_key(interval):
        try:
            return float(N(interval.inf, 15))
        except Exception:
            return 0.0

    gold_args.sort(key=sort_key)
    target_args.sort(key=sort_key)
    return all(
        _interval_eq(g, t, float_rounding, numeric_precision)
        for g, t in zip(gold_args, target_args)
    )


def _finset_eq(
    gold: FiniteSet,
    target: FiniteSet,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    """True iff a perfect pairwise matching between set elements exists."""
    gold_args, target_args = list(gold.args), list(target.args)
    if len(gold_args) != len(target_args):
        return False
    for permutation in permutations(range(len(target_args))):
        if all(
            sympy_expr_eq(
                gold_arg,
                target_args[permutation[i]],
                float_rounding,
                numeric_precision,
                allow_set_relation_comp=allow_set_relation_comp,
                strict=strict,
            )
            for i, gold_arg in enumerate(gold_args)
        ):
            return True
    return False


def _relational_eq(gold: Relational, target: Relational, float_rounding: int, numeric_precision: int) -> bool:
    """True iff two relationals are equivalent up to a consistent sign flip."""
    e1 = gold.lhs - gold.rhs
    e2 = target.lhs - target.rhs
    # Same residual: directions must match exactly (Eq with Eq, Ge with Ge, ...).
    if _is_zero(e1 - e2, float_rounding, numeric_precision):
        return type(gold) is type(target)
    # Opposite residuals: directions must be exact reverses (Ge <-> Le, ...).
    if _is_zero(e1 + e2, float_rounding, numeric_precision):
        return _REVERSE_RELATIONAL.get(type(gold)) is type(target)
    return False


def _is_relation_like(expr) -> bool:
    """True for (conjunctions/disjunctions of) relational expressions."""
    if isinstance(expr, Relational):
        return True
    if isinstance(expr, (And, Or)):
        return all(isinstance(arg, Relational) for arg in expr.args)
    return False


def _relation_to_set(expr, var: Symbol):
    """Convert a (compound) univariate relation to its solution set."""
    if isinstance(expr, And):
        sets = [_relation_to_set(arg, var) for arg in expr.args]
        result = sets[0]
        for solution_set in sets[1:]:
            result = Intersection(result, solution_set)
        return result
    if isinstance(expr, Or):
        sets = [_relation_to_set(arg, var) for arg in expr.args]
        result = sets[0]
        for solution_set in sets[1:]:
            result = SympyUnion(result, solution_set)
        return result
    return solve_univariate_inequality(expr, var, relational=False)


def _set_eq(
    gold,
    target,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    """Compare two sympy sets (intervals, unions of intervals, finite sets)."""
    if isinstance(gold, Interval) and isinstance(target, Interval):
        return _interval_eq(gold, target, float_rounding, numeric_precision)
    if isinstance(gold, SympyUnion) and isinstance(target, SympyUnion):
        return _union_eq(gold, target, float_rounding, numeric_precision)
    if isinstance(gold, FiniteSet) and isinstance(target, FiniteSet):
        return _finset_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)
    return False


def sympy_expr_eq(
    gold: Union[Basic, MatrixBase],
    target: Union[Basic, MatrixBase],
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
) -> bool:
    """Check whether two parsed sympy expressions are mathematically equal.

    Applies, in order: structural equality, symbol-name strictness (with
    sorted-name substitution in non-strict mode), numeric closeness,
    relational equivalence, interval/union/finite-set/tuple/matrix comparison,
    relation-vs-set conversion, and finally general symbolic simplification.
    """
    # 1. Structural equality.
    try:
        if gold == target:
            return True
    except Exception:
        pass

    # 2. Symbol-name strictness. In strict mode, differing symbol names mean
    # the expressions cannot be equal. In non-strict mode with equally many
    # symbols, rename the target's symbols to the gold's by sorted-name order.
    gold_symbols = _symbol_names(gold)
    target_symbols = _symbol_names(target)
    if gold_symbols != target_symbols and gold_symbols and target_symbols:
        if strict:
            return False
        if len(gold_symbols) == len(target_symbols):
            try:
                mapping = {
                    Symbol(target_name): Symbol(gold_name)
                    for gold_name, target_name in zip(sorted(gold_symbols), sorted(target_symbols))
                }
                target = target.subs(mapping, simultaneous=True)
                if gold == target:
                    return True
            except Exception:
                pass

    # 3. Pure numbers: numeric closeness at the requested rounding.
    try:
        if (
            getattr(gold, "is_number", False)
            and getattr(target, "is_number", False)
            and not _free_symbols(gold)
            and not _free_symbols(target)
        ):
            return _numeric_close(gold, target, float_rounding, numeric_precision)
    except Exception:
        pass

    # 4. Relationals (Eq, Ne, Lt, Le, Gt, Ge).
    try:
        if isinstance(gold, Relational) and isinstance(target, Relational):
            return _relational_eq(gold, target, float_rounding, numeric_precision)
    except Exception:
        pass

    # 5./6. Intervals and unions of intervals.
    try:
        if isinstance(gold, (Interval, SympyUnion)) and isinstance(target, (Interval, SympyUnion)):
            return _set_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)
    except Exception:
        pass

    # 7. Finite sets: any perfect pairwise matching.
    try:
        if isinstance(gold, FiniteSet) and isinstance(target, FiniteSet):
            return _finset_eq(gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict)
    except Exception:
        pass

    # 8. Tuples: ordered, elementwise.
    try:
        if isinstance(gold, Tuple) and isinstance(target, Tuple):
            if len(gold.args) != len(target.args):
                return False
            return all(
                sympy_expr_eq(
                    g, t, float_rounding, numeric_precision,
                    allow_set_relation_comp=allow_set_relation_comp, strict=strict,
                )
                for g, t in zip(gold.args, target.args)
            )
    except Exception:
        pass

    # 9. Matrices: same shape, elementwise.
    try:
        if isinstance(gold, MatrixBase) and isinstance(target, MatrixBase):
            if gold.shape != target.shape:
                return False
            return all(
                sympy_expr_eq(
                    g, t, float_rounding, numeric_precision,
                    allow_set_relation_comp=allow_set_relation_comp, strict=strict,
                )
                for g, t in zip(gold, target)
            )
    except Exception:
        pass

    # 10. Relation vs set: convert a univariate (compound) inequality to its
    # solution set and compare. Interval/Union comparisons always apply;
    # FiniteSet comparisons only when allow_set_relation_comp is enabled
    # (e.g. Eq(x, v) against {v}).
    try:
        allowed_sets = (Interval, SympyUnion, FiniteSet) if allow_set_relation_comp else (Interval, SympyUnion)
        relation, solution = None, None
        if _is_relation_like(gold) and isinstance(target, allowed_sets):
            relation, solution = gold, target
        elif _is_relation_like(target) and isinstance(gold, allowed_sets):
            relation, solution = target, gold
        if relation is not None:
            relation_symbols = _free_symbols(relation)
            if len(relation_symbols) == 1:
                converted = _relation_to_set(relation, relation_symbols.pop())
                return _set_eq(converted, solution, float_rounding, numeric_precision, allow_set_relation_comp, strict)
    except Exception:
        pass

    # 11. General symbolic equality: simplify the difference to zero (with a
    # trigsimp fallback, and an evalf-based comparison for constants).
    try:
        return _is_zero(gold - target, float_rounding, numeric_precision)
    except Exception:
        pass

    return False


def _ensure_sympy(value):
    """Coerce plain Python numbers to sympy objects; None on failure."""
    if isinstance(value, (Basic, MatrixBase)):
        return value
    try:
        coerced = sympify(value)
        if isinstance(coerced, (Basic, MatrixBase)):
            return coerced
    except Exception:
        pass
    return None


def verify(
    gold: Union[List[Union[Basic, MatrixBase, str]], Basic, MatrixBase, str],
    target: Union[List[Union[Basic, MatrixBase, str]], Basic, MatrixBase, str],
    float_rounding: int = 6,
    numeric_precision: int = 15,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
    timeout_seconds: Optional[int] = 5,
) -> bool:
    """Verify whether any (gold_item, target_item) pair matches.

    Strings compare by stripped (case-insensitive) equality; a string never
    matches a sympy object. Sympy pairs compare via :func:`sympy_expr_eq`;
    any exception in a pair comparison counts as a non-match. The whole
    comparison is bounded by ``timeout_seconds`` (None disables the timeout);
    on timeout False is returned.
    """
    if gold is None or target is None:
        return False
    if not isinstance(gold, list):
        gold = [gold]
    if not isinstance(target, list):
        target = [target]
    if len(gold) == 0 or len(target) == 0:
        return False

    def compare_pairs() -> bool:
        for gold_item in gold:
            for target_item in target:
                if isinstance(gold_item, str) or isinstance(target_item, str):
                    if isinstance(gold_item, str) and isinstance(target_item, str):
                        gold_str, target_str = gold_item.strip(), target_item.strip()
                        if gold_str == target_str or gold_str.lower() == target_str.lower():
                            return True
                    # A string never matches a sympy object.
                    continue
                gold_expr = _ensure_sympy(gold_item)
                target_expr = _ensure_sympy(target_item)
                if gold_expr is None or target_expr is None:
                    continue
                try:
                    if sympy_expr_eq(
                        gold_expr,
                        target_expr,
                        float_rounding,
                        numeric_precision,
                        allow_set_relation_comp=allow_set_relation_comp,
                        strict=strict,
                    ):
                        return True
                except TimeoutException:
                    # Never swallow the alarm: propagate it to verify's handler.
                    raise
                except Exception:
                    continue
        return False

    if timeout_seconds is None:
        return compare_pairs()

    alarm_installed = False
    previous_handler = None
    try:
        def timeout_handler(signum, frame):
            raise TimeoutException()

        previous_handler = signal.signal(signal.SIGALRM, timeout_handler)
        signal.alarm(int(timeout_seconds))
        alarm_installed = True
    except (ValueError, AttributeError):
        # signal only works in the main thread; proceed without the alarm.
        pass

    try:
        return compare_pairs()
    except TimeoutException:
        return False
    finally:
        if alarm_installed:
            signal.alarm(0)
            signal.signal(signal.SIGALRM, previous_handler)

